-- Unified Semantic Layer 'causeway': tables, relationships, activation
-- Generated by scripts/onboard.ts from src/data/eurostat.ts. One statement per call (Zetaris Lightning SQL).
-- The COMPILE USL statement is multi-table and must be sent as ONE statement.

-- metastore root (needed once per instance)
CREATE NAMESPACE IF NOT EXISTS lightning.metastore;

-- namespace
CREATE NAMESPACE IF NOT EXISTS lightning.metastore.causeway_ns;

-- compile USL causeway
COMPILE USL IF NOT EXISTS causeway DEPLOY NAMESPACE lightning.metastore.causeway_ns DDL
CREATE TABLE business (
    business_id varchar(64) NOT NULL PRIMARY KEY,
    name varchar(200) NOT NULL,
    city varchar(100),
    nace varchar(16),
    sector varchar(200),
    synthetic boolean NOT NULL
);
CREATE TABLE calendar_month (
    period varchar(7) NOT NULL PRIMARY KEY,
    easter_date varchar(10),
    easter_share double,
    days_in_month int
);
CREATE TABLE driver_series (
    series_id varchar(32) NOT NULL PRIMARY KEY,
    dataset varchar(32) NOT NULL,
    label varchar(300),
    unit_label varchar(64),
    source_grain varchar(16),
    licence varchar(200)
);
CREATE TABLE business_period (
    row_key varchar(80) NOT NULL PRIMARY KEY,
    business_id varchar(64) NOT NULL FOREIGN KEY REFERENCES business(business_id),
    period varchar(7) NOT NULL FOREIGN KEY REFERENCES calendar_month(period),
    units int,
    transactions int,
    revenue double,
    cogs double,
    gross_margin_pct double,
    avg_ticket double,
    synthetic boolean NOT NULL
);
CREATE TABLE driver_month (
    obs_key varchar(48) NOT NULL PRIMARY KEY,
    series_id varchar(32) NOT NULL FOREIGN KEY REFERENCES driver_series(series_id),
    period varchar(7) NOT NULL FOREIGN KEY REFERENCES calendar_month(period),
    value double,
    source_period varchar(8)
);;

-- describe USL
UPDATE USL lightning.metastore.causeway_ns.causeway SET DESCRIPTION 'Causeway: a small business ledger federated with Eurostat drivers for evidence-backed why-questions. Ledger data is synthetic and labelled.';

-- activate business
ACTIVATE USL TABLE lightning.metastore.causeway_ns.causeway.business AS SELECT business_id, name, city, nace, sector, synthetic FROM causeway_ledger.businesses;

-- activate calendar_month
ACTIVATE USL TABLE lightning.metastore.causeway_ns.causeway.calendar_month AS SELECT period, easter_date, easter_share, days_in_month FROM causeway_ledger.calendar_monthly;

-- activate driver_series
ACTIVATE USL TABLE lightning.metastore.causeway_ns.causeway.driver_series AS SELECT 'hicp_choc_i15' AS series_id, 'prc_hicp_midx' AS dataset, 'HICP Belgium - chocolate (2015=100)' AS label, 'index 2015=100' AS unit_label, 'month' AS source_grain, 'Eurostat, re-use with attribution' AS licence
UNION ALL
SELECT 'hicp_choc_i25' AS series_id, 'prc_hicp_minr' AS dataset, 'HICP Belgium - chocolate (2025=100, ECOICOP v2)' AS label, 'index 2025=100' AS unit_label, 'month' AS source_grain, 'Eurostat, re-use with attribution' AS licence
UNION ALL
SELECT 'elec_nonhh' AS series_id, 'nrg_pc_205' AS dataset, 'Electricity price, non-household 20-499 MWh, excl. VAT (Belgium)' AS label, 'EUR/kWh' AS unit_label, 'half_year' AS source_grain, 'Eurostat, re-use with attribution' AS licence
UNION ALL
SELECT 'gas_nonhh' AS series_id, 'nrg_pc_203' AS dataset, 'Gas price, non-household 1,000-9,999 GJ, excl. VAT (Belgium)' AS label, 'EUR/kWh' AS unit_label, 'half_year' AS source_grain, 'Eurostat, re-use with attribution' AS licence
UNION ALL
SELECT 'retail_vol_g47' AS series_id, 'sts_trtu_m' AS dataset, 'Retail trade volume, Belgium (G47, calendar adjusted, 2021=100)' AS label, 'index 2021=100' AS unit_label, 'month' AS source_grain, 'Eurostat, re-use with attribution' AS licence
UNION ALL
SELECT 'tourism_nights' AS series_id, 'tour_occ_nim' AS dataset, 'Nights spent in tourist accommodation, Belgium' AS label, 'nights' AS unit_label, 'month' AS source_grain, 'Eurostat, re-use with attribution' AS licence
UNION ALL
SELECT 'bankruptcies_g' AS series_id, 'sts_rb_q' AS dataset, 'Bankruptcy declarations, wholesale and retail trade (G), Belgium (2021=100)' AS label, 'index 2021=100' AS unit_label, 'quarter' AS source_grain, 'Eurostat, re-use with attribution' AS licence;

-- activate business_period
ACTIVATE USL TABLE lightning.metastore.causeway_ns.causeway.business_period AS SELECT concat(business_id, ':', period) AS row_key, business_id, period, units, transactions, revenue, cogs, gross_margin_pct, avg_ticket, synthetic FROM causeway_ledger.ledger_monthly;

-- activate driver_month
ACTIVATE USL TABLE lightning.metastore.causeway_ns.causeway.driver_month AS SELECT COALESCE(concat(series_id, ':', period), '') AS obs_key, series_id, COALESCE(period, '') AS period, value, source_period FROM (
SELECT 'hicp_choc_i15' AS series_id, d.src_period AS period, d.value AS value, d.src_period AS source_period FROM (SELECT time_label AS src_period, CAST(v AS DOUBLE) AS value
FROM eurostat_rest.hicp_choc_i15
LATERAL VIEW explode(from_json(to_json(value), 'map<string,double>')) AS time_key, v
LATERAL VIEW explode(from_json(to_json(dimension.time.category.index), 'map<string,bigint>')) AS time_label, idx
WHERE CAST(time_key AS INT) = idx) d
UNION ALL
SELECT 'hicp_choc_i25' AS series_id, d.src_period AS period, d.value AS value, d.src_period AS source_period FROM (SELECT time_label AS src_period, CAST(v AS DOUBLE) AS value
FROM eurostat_rest.hicp_choc_i25
LATERAL VIEW explode(from_json(to_json(value), 'map<string,double>')) AS time_key, v
LATERAL VIEW explode(from_json(to_json(dimension.time.category.index), 'map<string,bigint>')) AS time_label, idx
WHERE CAST(time_key AS INT) = idx) d
UNION ALL
SELECT 'elec_nonhh' AS series_id,
  concat(substr(d.src_period, 1, 4), '-', lpad(CAST((CAST(substr(d.src_period, 7, 1) AS INT) - 1) * 6 + m AS STRING), 2, '0')) AS period,
  d.value AS value, d.src_period AS source_period
FROM (SELECT time_label AS src_period, CAST(v AS DOUBLE) AS value
FROM eurostat_rest.elec_nonhh
LATERAL VIEW explode(from_json(to_json(value), 'map<string,double>')) AS time_key, v
LATERAL VIEW explode(from_json(to_json(dimension.time.category.index), 'map<string,bigint>')) AS time_label, idx
WHERE CAST(time_key AS INT) = idx) d LATERAL VIEW explode(sequence(1, 6)) AS m
WHERE substr(d.src_period, 6, 1) = 'S'
UNION ALL
SELECT 'gas_nonhh' AS series_id,
  concat(substr(d.src_period, 1, 4), '-', lpad(CAST((CAST(substr(d.src_period, 7, 1) AS INT) - 1) * 6 + m AS STRING), 2, '0')) AS period,
  d.value AS value, d.src_period AS source_period
FROM (SELECT time_label AS src_period, CAST(v AS DOUBLE) AS value
FROM eurostat_rest.gas_nonhh
LATERAL VIEW explode(from_json(to_json(value), 'map<string,double>')) AS time_key, v
LATERAL VIEW explode(from_json(to_json(dimension.time.category.index), 'map<string,bigint>')) AS time_label, idx
WHERE CAST(time_key AS INT) = idx) d LATERAL VIEW explode(sequence(1, 6)) AS m
WHERE substr(d.src_period, 6, 1) = 'S'
UNION ALL
SELECT 'retail_vol_g47' AS series_id, d.src_period AS period, d.value AS value, d.src_period AS source_period FROM (SELECT time_label AS src_period, CAST(v AS DOUBLE) AS value
FROM eurostat_rest.retail_vol_g47
LATERAL VIEW explode(from_json(to_json(value), 'map<string,double>')) AS time_key, v
LATERAL VIEW explode(from_json(to_json(dimension.time.category.index), 'map<string,bigint>')) AS time_label, idx
WHERE CAST(time_key AS INT) = idx) d
UNION ALL
SELECT 'tourism_nights' AS series_id, d.src_period AS period, d.value AS value, d.src_period AS source_period FROM (SELECT time_label AS src_period, CAST(v AS DOUBLE) AS value
FROM eurostat_rest.tourism_nights
LATERAL VIEW explode(from_json(to_json(value), 'map<string,double>')) AS time_key, v
LATERAL VIEW explode(from_json(to_json(dimension.time.category.index), 'map<string,bigint>')) AS time_label, idx
WHERE CAST(time_key AS INT) = idx) d
UNION ALL
SELECT 'bankruptcies_g' AS series_id,
  concat(substr(d.src_period, 1, 4), '-', lpad(CAST((CAST(substr(d.src_period, 7, 1) AS INT) - 1) * 3 + m AS STRING), 2, '0')) AS period,
  d.value AS value, d.src_period AS source_period
FROM (SELECT time_label AS src_period, CAST(v AS DOUBLE) AS value
FROM eurostat_rest.bankruptcies_g
LATERAL VIEW explode(from_json(to_json(value), 'map<string,double>')) AS time_key, v
LATERAL VIEW explode(from_json(to_json(dimension.time.category.index), 'map<string,bigint>')) AS time_label, idx
WHERE CAST(time_key AS INT) = idx) d LATERAL VIEW explode(sequence(1, 3)) AS m
WHERE substr(d.src_period, 6, 1) = 'Q'
) AS drivers;
